-- V351__tankeroutbound_v87_tank_allocation_and_reload.sql
-- Sets M10.TankerOutbound's PUBLISHED workflow_definition to the exact
-- tenant-1 "v87" body (version column = 87) as authored in the team's
-- Workflow Designer — pulled verbatim from a live export, not reconstructed,
-- so this migration is a faithful byte-for-byte mirror of the real system,
-- including its harmless orphaned state declarations (BAY_ASSIGNED,
-- LOADING_IN_PROGRESS, WEIGHMENT_1, PARKING_OUT_1, PARKING_IN_2,
-- PARKING_OUT_2, and a duplicate WEIGHT_APPROVAL_PENDING entry) that no
-- transition in this body ever references — left in place rather than
-- "cleaned up" so this migration can't silently diverge from the source of
-- truth. An earlier version of this migration reconstructed the body by
-- hand from a pasted transition table and dropped those orphans; verified
-- against the real export that every actual transition was already
-- identical, so this replacement only restores the inert extras.
--
-- Shape: DISPATCH_LOADING_PLANNING -> tank allocation at QC_PRELOAD_APPROVED
-- (QcPreloadTankAllocationListener) -> straight to LOADING_COMPLETED via
-- aria:weighment-capture, plus the reload cycle:
--   RELOAD_REQUIRED -> UNLOADING_WEIGHMENT -> RELOAD_LOADING -> LOADING_COMPLETED
-- all three hosted on aria:weighment-capture, no separate unload page.
--
-- Manager-reject edges (WEIGHT_DIFF_PENDING_MANAGER/WEIGHT_APPROVAL_PENDING
-- -> REJECTED_BY_MANAGER) still go to REJECTED_BY_MANAGER here, matching the
-- real system as of this export — repointing them at RELOAD_REQUIRED is a
-- separate, later change once the backend pieces are confirmed.
--
-- Idempotent full-body set.
UPDATE workflow_definition
   SET body_json = '{"code":"M10.TankerOutbound","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"DISPATCH_VEHICLE_ENTRY","assignedRole":"QC"},{"code":"QC_PRELOAD_APPROVED","assignedRole":"WeighmentOfficer"},{"code":"QC_PRELOAD_REJECTED","terminal":true},{"code":"PARKING_OUT_1","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_1","assignedRole":"LoadingSupervisor"},{"code":"LOADING_IN_PROGRESS","assignedRole":"LoadingSupervisor"},{"code":"QC_SAMPLE_APPROVED","assignedRole":"WeighmentOfficer"},{"code":"QC_SAMPLE_REJECTED","terminal":true},{"code":"WEIGHMENT_2","assignedRole":"Manager"},{"code":"PARKING_IN_2","assignedRole":"Dispatch"},{"code":"WEIGHT_DIFF_OK","assignedRole":"BillingOfficer"},{"code":"WEIGHT_DIFF_PENDING_MANAGER","assignedRole":"Manager"},{"code":"BILLING_DONE","assignedRole":"WeighmentOfficer"},{"code":"PARKING_OUT_2","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_3","assignedRole":"Manager"},{"code":"READY_FOR_EXIT","assignedRole":"FrontGate"},{"code":"GATE_PASS_OUT_CLOSED","terminal":true},{"code":"REJECTED_BY_MANAGER","terminal":true},{"code":"BAY_ASSIGNED","assignedRole":"LoadingSupervisor"},{"code":"LOADING_COMPLETED","assignedRole":"QC"},{"code":"DISPATCH_LOADING_PLANNING","assignedRole":"Dispatch"},{"code":"WEIGHT_APPROVAL_PENDING","assignedRole":"Manager"},{"code":"WEIGHT_APPROVAL_PENDING","assignedRole":"Manager"},{"code":"RELOAD_REQUIRED","assignedRole":"WeighmentOfficer","terminal":false},{"code":"UNLOADING_WEIGHMENT","assignedRole":"WeighmentOfficer"},{"code":"RELOAD_LOADING","assignedRole":"WeighmentOfficer"}],"transitions":[{"from":"DRAFT","to":"DISPATCH_VEHICLE_ENTRY","trigger":"page.submitted","pageCode":"aria:dispatch-vehicle-details"},{"from":"DISPATCH_LOADING_PLANNING","to":"QC_PRELOAD_APPROVED","trigger":"page.submitted","pageCode":"aria:qc-preload-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"DISPATCH_LOADING_PLANNING","to":"QC_PRELOAD_REJECTED","trigger":"page.submitted","pageCode":"aria:qc-preload-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QC_PRELOAD_APPROVED","to":"LOADING_COMPLETED","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"LOADING_COMPLETED","to":"QC_SAMPLE_APPROVED","trigger":"page.submitted","pageCode":"aria:qc-final-out","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"LOADING_COMPLETED","to":"QC_SAMPLE_REJECTED","trigger":"page.submitted","pageCode":"aria:qc-final-out","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QC_SAMPLE_APPROVED","to":"WEIGHMENT_2","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_2","to":"WEIGHT_DIFF_OK","trigger":"page.submitted","pageCode":"aria:manager-qty-approval","guard":"#submitted[''withinTolerance''] == ''YES''"},{"from":"WEIGHMENT_2","to":"WEIGHT_DIFF_PENDING_MANAGER","trigger":"page.submitted","pageCode":"aria:manager-qty-approval","guard":"#submitted[''withinTolerance''] == ''NO''"},{"from":"WEIGHT_DIFF_PENDING_MANAGER","to":"WEIGHT_DIFF_OK","trigger":"page.submitted","pageCode":"aria:manager-qty-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHT_DIFF_PENDING_MANAGER","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"aria:manager-qty-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"WEIGHT_DIFF_OK","to":"BILLING_DONE","trigger":"page.submitted","pageCode":"aria:billing-entry"},{"from":"BILLING_DONE","to":"WEIGHMENT_3","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_3","to":"READY_FOR_EXIT","trigger":"page.submitted","pageCode":"aria:manager-weight-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHMENT_3","to":"BILLING_DONE","trigger":"page.submitted","pageCode":"aria:manager-weight-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"READY_FOR_EXIT","to":"GATE_PASS_OUT_CLOSED","trigger":"page.submitted","pageCode":"aria:gate-pass-closure-form","guard":"(#submitted[''weighment_verified''] == ''OK'' || #submitted[''weighment_verified''] == ''MGR_APPROVED'') && (#submitted[''seal_verified''] == ''MATCHED'' || #submitted[''seal_verified''] == ''NA'') && #submitted[''invoice_count_verified''] == ''YES''"},{"from":"DISPATCH_VEHICLE_ENTRY","to":"DISPATCH_LOADING_PLANNING","trigger":"page.submitted","pageCode":"aria:loading-planning-order-sheet-upload","guard":""},{"from":"READY_FOR_EXIT","to":"WEIGHT_APPROVAL_PENDING","trigger":"page.submitted","pageCode":"aria:gate-pass-closure-form","guard":"#submitted[''report_weight_diff''] == ''true''"},{"from":"WEIGHT_APPROVAL_PENDING","to":"READY_FOR_EXIT","trigger":"page.submitted","pageCode":"aria:manager-weight-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHT_APPROVAL_PENDING","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"aria:manager-weight-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"RELOAD_REQUIRED","to":"UNLOADING_WEIGHMENT","trigger":"page.submitted","pageCode":"aria:weighment-capture","guard":""},{"from":"UNLOADING_WEIGHMENT","to":"RELOAD_LOADING","trigger":"page.submitted","pageCode":"aria:weighment-capture","guard":""},{"from":"RELOAD_LOADING","to":"LOADING_COMPLETED","trigger":"page.submitted","pageCode":"aria:weighment-capture","guard":""}]}'
 WHERE code = 'M10.TankerOutbound' AND status = 'PUBLISHED';
